// Reports a failed execution back to LendLoop so it is visible in the app and
// not only in n8n's execution history.
const crypto = require('crypto');
const secret = $env.LENDLOOP_SHARED_SECRET;
const siteUrl = $env.LENDLOOP_SITE_URL;

const trigger = $input.first().json;
const execution = trigger.execution ?? {};
const workflow = trigger.workflow ?? {};

const executionId = String(execution.id ?? 'unknown');
const workflowName = String(workflow.name ?? 'unknown workflow');
const lastNode = String(execution.lastNodeExecuted ?? 'unknown node');
const errorMessage =
  execution.error?.message ?? execution.data?.resultData?.error?.message ?? 'Unknown error';

const body = JSON.stringify({
  workflow: workflowName,
  detail: `${lastNode}: ${errorMessage}`.slice(0, 280),
});

const timestamp = String(Math.floor(Date.now() / 1000));
const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.${body}`).digest('hex');

return [
  {
    json: {
      body,
      timestamp,
      signature,
      // One notification per failed execution, so a retried report collapses.
      idempotencyKey: `workflow-failure:${workflowName}:${executionId}`,
    },
  },
];
